def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]; seen=set()
 for i in range(h):
  for j in range(w):
   if (i,j) in seen: continue
   c=grid[i][j]; q=[(i,j)]; seen.add((i,j)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==c:
      seen.add((a,b));q.append((a,b))
   if len(comp)==1:
    x,y=comp[0]
